/**
 * Room classification: a deterministic, rule-based classifier. It is NOT a trained model and must never be described as one.
 *
 * Ported line for line from `v25RoomClassifyCompute` (src/v25-60-room.js) and `recommendArch` (src/58-derive-eng.js).
 * Parity with the demonstrator is checked against 92 golden cases (test/parity.test.ts).
 */
import type { Classification, Complexity, PlannedDevice, RoomDesignInput, SizeCategory } from '@empathia/domain-types';
import { area } from './geometry.js';
import { type Catalog, defaultCatalog } from './catalog.js';

/** Equipment category → commissioning device family (the families the rule pack and the discipline packs name). */
export function deviceFamily(cat: string): string | null {
  const map: Record<string, string> = {
    camera: 'camera', bar: 'camera',
    micceil: 'dsp', mictable: 'dsp', micwireless: 'dsp', dsp: 'dsp', speaker: 'dsp', amp: 'dsp',
    touch: 'touch_panel', control: 'touch_panel',
    switch: 'network_switch',
    display: 'display', ledwall: 'display', projector: 'display',
    lighting: 'lighting', compute: 'uc', scheduler: 'signage',
  };
  return map[cat] ?? null;
}

/** The archetype a use and a head-count suggest (src/58-derive-eng.js `recommendArch`). */
export function recommendArch(use: string, cap: number, people?: string): string {
  const n = Number(cap) || 8;
  // a townhall and a control room are one-off designs: Room Builder lays out the archetypes that follow a template
  if (use === 'training' || use === 'event') return 'TRN';
  if (use === 'produce') return 'STU';
  if (use === 'operate') return 'WAR';
  if (use === 'focus') return n <= 4 ? 'FOC' : 'HUD';
  if (n <= 4) return 'FOC';
  if (n <= 6) return 'HUD';
  if (n <= 12) return people === 'leaders' && n >= 10 ? 'EXE' : 'COL';
  if (n <= 14) return 'EXE';
  return 'BRD';
}

export const liveDevices = (d: Pick<RoomDesignInput, 'devices'>): PlannedDevice[] => d.devices.filter((x) => !x.removed);

const AV_CATS = ['display', 'ledwall', 'projector', 'camera', 'bar', 'micceil', 'mictable', 'micwireless', 'speaker'];

/** Classify a room from its declared geometry, intended use, occupancy and equipment. Returns the reasons and the assumptions. */
export function classifyRoom(d: RoomDesignInput, C: Catalog = defaultCatalog): Classification {
  const a = area(d.geometry);
  const live = liveDevices(d);
  const cats = new Set(live.map((x) => x.cat));
  const why: string[] = [];
  const assumptions: string[] = [];
  const seats = live.filter((x) => x.cat === 'chairs').reduce((s, x) => s + (Number(x.props['seats']) || 6), 0);
  const density = d.occupancy >= 60 || /town|auditor|all-hands|event|lecture/i.test(d.intendedUse) ? 0.9 : 2.2;
  const capEst = Math.max(1, Math.floor(a / density));
  assumptions.push(
    `capacity estimate = floor area ${a} m² ÷ ${density} m² per person (${density < 1 ? 'theatre-style seating' : 'meeting seating'}); a planning assumption, not a fire-code occupancy`,
  );
  const people = d.occupancy || seats || capEst;
  const u = String(d.intendedUse || '');
  const useKey = /train|teach|class|lectur/i.test(u)
    ? 'training'
    : /event|all-hands|town/i.test(u)
      ? 'event'
      : /record|stream|studio|broadcast/i.test(u)
        ? 'produce'
        : /operat|control room|war room/i.test(u)
          ? 'operate'
          : /focus|one person|desk/i.test(u)
            ? 'focus'
            : '';
  let arch: string | null = recommendArch(useKey, people, /leader|executive|board/i.test(u) ? 'leaders' : 'team');
  const tpl = C.templates[d.template];
  const tplArch = tpl ? tpl.arch ?? undefined : undefined;
  if (typeof arch !== 'string' || !C.archetypes[arch]) arch = null;
  const hasAv = AV_CATS.some((c) => cats.has(c));
  if (!hasAv && cats.has('rack') && cats.has('switch')) {
    arch = 'CTL';
    why.push('equipment rack and network switch, no room AV: an equipment / IDF room');
  } else if (!hasAv) {
    arch = null;
    why.push('no displays, cameras, microphones or loudspeakers: not a meeting space (building systems only)');
  } else if (people >= 100 || a >= 250) {
    arch = 'TWN';
    why.push(`${people} people / ${a} m²: a town hall or multipurpose space`);
  } else if (tplArch && (!arch || C.archetypes[tplArch]!.cap[0] <= people * 1.5)) {
    arch =
      arch && arch !== tplArch && Math.abs(C.archetypes[arch]!.cap[0] - people) < Math.abs(C.archetypes[tplArch]!.cap[0] - people)
        ? arch
        : tplArch;
    why.push(`template ${tpl!.label} and ${people} people`);
  } else if (arch) {
    why.push(`intended use “${d.intendedUse || 'not stated'}” and ${people} people`);
  }
  const size: SizeCategory = a < 15 ? 'small' : a < 40 ? 'medium' : a < 100 ? 'large' : 'extra large';
  why.push(`floor area ${a} m² → ${size}`);
  const fams = new Set(live.map((x) => deviceFamily(x.cat)).filter((f): f is string => !!f));
  const n = live.filter((x) => !x.furniture).length;
  const tier: Complexity = arch === 'TWN' || n >= 14 ? 'critical' : n >= 8 || fams.size >= 5 ? 'advanced' : n >= 4 || fams.size >= 3 ? 'standard' : 'basic';
  why.push(`${n} devices across ${fams.size} families → ${tier} technology complexity`);
  const sub = tpl?.sub || (arch ? C.archetypes[arch]!.name.toLowerCase() : 'not a meeting space');
  const conf = d.geometry.confidence === 'declared' && d.intendedUse ? 'medium' : 'low';
  if (conf === 'low') assumptions.push('dimensions or intended use are not declared: the classification rests on template defaults');
  return {
    archetype: arch,
    archetypeName: arch ? C.archetypes[arch]!.name : 'Not a meeting space',
    subtype: sub,
    intendedUse: d.intendedUse || 'not stated',
    capacityEstimate: capEst,
    people,
    sizeCategory: size,
    complexity: tier,
    families: [...fams],
    cxRoomType: arch ? C.roomType[arch] || 'boardroom' : null,
    source: 'rule-based classifier (v25-60) over declared geometry, intended use, occupancy and equipment',
    confidence: conf,
    why,
    assumptions,
  };
}

/**
 * The archetype the other engines act on: an engineer's approved classification unless it has gone stale
 * (the suggestion changed and the approval was not an override), otherwise the current suggestion.
 */
export function effectiveArchetype(d: RoomDesignInput, suggested: Classification): string | null {
  const ap = d.classification.approved;
  if (!ap) return suggested.archetype;
  const stale = !!ap.stale || (ap.archetype !== suggested.archetype && !ap.override);
  return stale ? suggested.archetype : ap.archetype;
}

/**
 * Commissioning applicability: judge every test definition in the library (33 base + 61 discipline-pack = 94 in 2.5.x) for one room.
 *
 * Each definition is APPLICABLE (with the rules that selected it) or NOT_APPLICABLE (with a justification). An applicable test gets
 * exactly one execution state: PENDING_INFORMATION (facts missing), BLOCKED_BY_PREREQUISITE (design not approved) or
 * REQUIRES_PHYSICAL_EXECUTION. The engine NEVER produces a pass: results only come from recorded field evidence (results.ts).
 *
 * Ported from `v25RoomApplicabilityCompute` (src/v25-60-room.js), `v25RequiredTests` (src/v25-05-design.js) and `v25CxApplies`
 * (src/v25-096-cxuni.js). Deterministic; O(T) in the library size with small constant per test.
 */
import type {
  Applicability, ApplicabilityContext, ApplicabilityRow, Classification, RoomDesignInput,
} from '@empathia/domain-types';
import { type Catalog, type PackApplies, type TestDefinition, defaultCatalog } from './catalog.js';
import { deviceFamily, liveDevices } from './classify.js';
import { resultLabel } from './results.js';

export interface RequiredTests {
  ids: string[];
  why: Record<string, string[]>;
  version: string;
}

/** The base rule pack: which of the 33 base tests a project needs, and why. */
export function requiredTests(
  p: { projectType: string; roomArchetype: string | null; risk?: string },
  opts: { families?: string[]; risk?: string | null; hasDevices?: boolean },
  C: Catalog = defaultCatalog,
): RequiredTests {
  const rp = C.rulePack;
  const ids: string[] = [];
  const why: Record<string, string[]> = {};
  const addAll = (list: string[] | undefined, reason: string) => {
    for (const t of list || []) {
      if (!ids.includes(t)) ids.push(t);
      (why[t] ||= []).push(reason);
    }
  };
  addAll(rp.base_tests.map((t) => t.id), 'base: every project');
  addAll(rp.project_types[p.projectType]?.tests, `project type ${p.projectType}`);
  const rt = p.roomArchetype ? C.roomType[p.roomArchetype] : undefined;
  if (rt) addAll(rp.room_types[rt]?.tests, `room type ${rt}`);
  for (const fam of opts.families || []) addAll(rp.devices[fam]?.tests, `device family ${fam}`);
  const risk = opts.risk || p.risk;
  if (risk && rp.risk[risk]) addAll(rp.risk[risk]!.tests, `risk ${risk}`);
  if (opts.hasDevices) addAll(['design_conformance'], 'V2.5 addition (+v21aliases): the released revision selects devices, so the installed inventory is checked against the drawing');
  if (rt === 'townhall') addAll(['reverberation_rt60'], 'V2.5 addition (rule version +v21aliases): townhall acoustic protocol needs reverberation time (ISO 3382-2) beside STIPA');
  return { ids, why, version: rp.version };
}

/** A discipline-pack test applies when every dimension it names matches the room context. */
export function packApplies(applies: PackApplies | undefined, ctx: ApplicabilityContext): { ok: boolean; why: string[]; whyNot: string[] } {
  const a = applies || {};
  const hit: string[] = [];
  const miss: string[] = [];
  const dim = (key: keyof PackApplies, vals: string[], label: string) => {
    const want = a[key];
    if (!want) return;
    const ok = want.some((v) => vals.includes(v));
    (ok ? hit : miss).push(`${label} ${want.join('/')}`);
  };
  dim('types', [ctx.type], 'project type');
  dim('rooms', [ctx.room], 'room type');
  dim('families', ctx.families, 'device family');
  dim('tiers', [ctx.tier], 'complexity');
  dim('risk', [ctx.risk], 'risk');
  return { ok: !miss.length, why: hit.length ? hit : ['applies to every project'], whyNot: miss };
}

/** The facts a design can supply. PHOTO_INFERRED dimensions do not count as facts. */
export function knownFacts(d: RoomDesignInput): Set<string> {
  const live = liveDevices(d);
  const f = new Set<string>();
  const pv = d.geometry.provenance;
  if (pv.ceiling !== 'PHOTO_INFERRED') f.add('ceiling height');
  if (pv.length !== 'PHOTO_INFERRED' && pv.width !== 'PHOTO_INFERRED') f.add('room dimensions');
  if (live.some((x) => x.cat === 'chairs' || x.cat === 'table')) f.add('seating');
  if (live.some((x) => ['micceil', 'mictable', 'micwireless', 'bar'].includes(x.cat))) f.add('microphone placement');
  if (live.some((x) => ['camera', 'bar'].includes(x.cat))) f.add('camera placement');
  if (d.connections.some((c) => !c.removed && c.kind === 'network')) f.add('network connections');
  if (live.some((x) => ['display', 'ledwall', 'projector'].includes(x.cat))) f.add('display placement');
  return f;
}

const APPROVED = ['DESIGN_APPROVED', 'INSTALLATION_PENDING', 'INSTALLED_UNVERIFIED', 'COMMISSIONING', 'ACCEPTED', 'OPERATIONAL'];
const INSTALLED = ['INSTALLED_UNVERIFIED', 'COMMISSIONING', 'ACCEPTED', 'OPERATIONAL'];
const DOMAIN_FAMILY: Record<string, string> = { Video: 'camera', Audio: 'dsp', Acoustic: 'dsp', Display: 'display', Network: 'network_switch', Control: 'touch_panel' };

/**
 * Judge the whole library for a room.
 * @param arch the effective archetype (see classify.effectiveArchetype)
 * @param suggested the current suggested classification (its complexity sets the tier)
 */
export function computeApplicability(d: RoomDesignInput, arch: string | null, suggested: Pick<Classification, 'complexity'>, C: Catalog = defaultCatalog): Applicability {
  const live = liveDevices(d).filter((x) => !x.furniture);
  const fams = new Set(live.map((x) => deviceFamily(x.cat)).filter((f): f is string => !!f));
  if (fams.has('touch_panel') && arch !== 'CTL') fams.add('uc');
  const tier = suggested.complexity || 'basic';
  const risk: 'standard' | 'critical' = tier === 'critical' ? 'critical' : 'standard';
  const req = requiredTests(
    { projectType: 'new_install', roomArchetype: arch, risk },
    { families: [...fams], risk: risk === 'standard' ? null : risk, hasDevices: live.length > 0 },
    C,
  );
  const roomType = arch ? C.roomType[arch] || 'boardroom' : 'none';
  const ctx: ApplicabilityContext = { type: 'new_install', room: roomType, families: [...fams], tier, risk };
  const facts = knownFacts(d);
  const approved = APPROVED.includes(d.lifecycle);
  const installed = INSTALLED.includes(d.lifecycle);
  const devRefs = (T: TestDefinition) => {
    const fam = T.family || DOMAIN_FAMILY[T.domain];
    const key = fam === 'touch' ? 'touch_panel' : fam;
    return live.filter((x) => key && deviceFamily(x.cat) === key).map((x) => x.id);
  };
  const rows: ApplicabilityRow[] = [];
  const judge = (id: string, T: TestDefinition, label: string, pack: string | null, ok: boolean, why: string[], whyNot: string) => {
    if (!ok) {
      rows.push({ id, label, pack: pack || null, domain: T.domain, phase: T.phase, tier: T.tier, applicable: false, status: 'NOT_APPLICABLE', why: [], justification: whyNot });
      return;
    }
    const need = (C.info[T.domain] || []).filter((x) => !facts.has(x));
    const status = need.length ? 'PENDING_INFORMATION' : !approved ? 'BLOCKED_BY_PREREQUISITE' : 'REQUIRES_PHYSICAL_EXECUTION';
    rows.push({
      id, label, pack: pack || null, domain: T.domain, phase: T.phase, tier: T.tier, applicable: true, status, why, missing: need,
      prerequisite: !approved
        ? 'the design is not approved (DESIGN_APPROVED is required before any field test)'
        : !installed && T.phase >= 2
          ? 'the room is not installed: the test needs physical execution on installed equipment'
          : null,
      verifier: T.verifier,
      personas: T.family ? [C.domainPersona[T.family]!] : C.verifierPersonas[T.verifier] || [],
      evidence: T.accepts,
      instrument: !!T.instrument,
      window: !!T.window,
      devices: devRefs(T),
      // R3-2: the machine-readable result is the same label every view and export shows — never a bare PASS.
      result: resultLabel((d.results || {})[id]),
    });
  };
  for (const [id, T] of Object.entries(C.tests)) {
    judge(id, T, C.testLabel[id] || id, null, req.ids.includes(id), req.why[id] || [], `no rule names it for new_install / ${roomType} / ${[...fams].join('+') || 'no device family'} / risk ${risk}`);
  }
  for (const [id, T] of Object.entries(C.packTests)) {
    if (C.tests[id]) continue;
    const j = packApplies(T.applies, ctx);
    judge(id, T, T.label, T.pack, j.ok, j.why.map((w) => `pack ${T.pack}: ${w}`), `pack ${T.pack}: needs ${j.whyNot.join(' and ')}; this room is new_install / ${roomType} / ${[...fams].join('+') || 'no family'} / ${tier}`);
  }
  rows.sort((a, b) => Number(b.applicable) - Number(a.applicable) || a.phase - b.phase || a.tier - b.tier || a.id.localeCompare(b.id));
  const packs = [...new Set(rows.filter((r) => r.applicable && r.pack).map((r) => r.pack!))];
  return {
    library: rows.length,
    applicable: rows.filter((r) => r.applicable).length,
    notApplicable: rows.filter((r) => !r.applicable).length,
    byStatus: rows.reduce<Applicability['byStatus']>((acc, r) => { acc[r.status] = (acc[r.status] || 0) + 1; return acc; }, {}),
    packs,
    ctx,
    rows,
  };
}

/**
 * Design checks: deterministic rules over the planned design. Every finding is a DESIGN_DEFICIENCY with a stable correlation key,
 * a severity and the rationale for that severity. Ported from `v25RoomChecks` (src/v25-60-room.js).
 *
 * The sightline and PoE checks use MODELED planning ratios and DECLARED catalogue values; they never claim a measurement.
 */
import type { Connection, DesignFinding, PlannedDevice, RoomDesignInput, Severity } from '@empathia/domain-types';
import { inside } from './geometry.js';
import { type Catalog, defaultCatalog } from './catalog.js';
import { liveDevices } from './classify.js';

export function designChecks(d: RoomDesignInput, arch: string | null, C: Catalog = defaultCatalog): DesignFinding[] {
  const out: DesignFinding[] = [];
  const live = liveDevices(d);
  const av = live.filter((x) => !x.furniture);
  const conns = d.connections.filter((c) => !c.removed);
  const byId = new Map(live.map((x) => [x.id, x] as const));
  const A = arch ? C.archetypes[arch] : undefined;
  const f = (key: string, check: string, severity: Severity, rationale: string, title: string, assets: string[], source: string, action: string) =>
    out.push({ key, category: 'DESIGN_DEFICIENCY', check, severity, rationale, title, assets: assets || [], source, action });

  // 1. required equipment for the room type
  for (const role of (arch && C.required[arch]) || []) {
    if (!live.some((x) => C.roleOk[role]!.includes(x.cat))) {
      f(
        `missing-equipment:${role}`, 'missing_required_equipment', 'High',
        `the ${A ? A.name : ''} room type requires a ${role} for its intended use`,
        `No ${role} in a ${A ? A.name.toLowerCase() : 'room'}`, [], 'design editor: required-equipment rule', `add a ${role} to the design`,
      );
    }
  }

  // 2. connectivity: breadth-first search over the proposed connections of the given kinds
  const reach = (from: string, kinds: string[], test: (y: PlannedDevice | undefined) => boolean): boolean => {
    const seen = new Set([from]);
    const q = [from];
    while (q.length) {
      const n = q.shift()!;
      for (const c of conns) {
        if (!kinds.includes(c.kind)) continue;
        const o = c.from === n ? c.to : c.to === n ? c.from : null;
        if (o && !seen.has(o)) {
          if (test(byId.get(o))) return true;
          seen.add(o);
          q.push(o);
        }
      }
    }
    return false;
  };
  const has = (cats: string[]) => live.some((y) => cats.includes(y.cat));
  const isAny = (cats: string[]) => (y: PlannedDevice | undefined) => !!y && cats.includes(y.cat);
  const netConn = (x: PlannedDevice, cs: Connection[]) => cs.some((c) => c.kind === 'network' && (c.from === x.id || c.to === x.id));

  for (const x of av) {
    const cat = C.categories[x.cat]!;
    if (['micceil', 'mictable', 'micwireless'].includes(x.cat) && has(['dsp']) && !reach(x.id, ['signal', 'network'], isAny(['dsp'])))
      f(`unresolved-connection:${x.id}:dsp`, 'unresolved_connection', 'High', 'a microphone without a path to the audio processor is not heard by anyone', `${x.label} has no signal path to the audio processor`, [x.id], 'connectivity check', 'propose the microphone → audio processor connection');
    if (x.cat === 'camera' && has(['compute', 'switcher']) && !reach(x.id, ['signal'], isAny(['compute', 'switcher'])))
      f(`unresolved-connection:${x.id}:compute`, 'unresolved_connection', 'High', 'a camera without a video path to the room compute sends no picture to the far end', `${x.label} has no video path to the room compute`, [x.id], 'connectivity check', 'propose the camera → room compute connection');
    if (x.cat === 'speaker' && has(['dsp', 'amp']) && !reach(x.id, ['signal'], isAny(['dsp', 'amp'])))
      f(`unresolved-connection:${x.id}:amp`, 'unresolved_connection', 'Medium', 'a loudspeaker with no amplifier or processor feed plays nothing', `${x.label} is not fed by an amplifier`, [x.id], 'connectivity check', 'connect the loudspeaker to an amplifier');
    if (['display', 'ledwall', 'projector'].includes(x.cat) && has(['compute', 'switcher']) && !reach(x.id, ['signal'], isAny(['compute', 'switcher'])))
      f(`unresolved-connection:${x.id}:source`, 'unresolved_connection', 'Medium', 'a display with no source shows nothing', `${x.label} has no source connection`, [x.id], 'connectivity check', 'connect the display to the room compute or the switcher');
    if (cat.net && has(['switch']) && x.cat !== 'switch' && !netConn(x, conns))
      f(`unresolved-connection:${x.id}:network`, 'unresolved_connection', 'Medium', 'a networked device without a network connection cannot be managed or monitored', `${x.label} has no network connection`, [x.id], 'network check', 'propose the device → switch connection');
    if (!x.furniture && !inside(d.geometry, x.x, x.y) && x.mount !== 'rack')
      f(`placement:${x.id}:outside`, 'placement_constraint', 'Medium', 'a device placed outside the room outline cannot be installed as drawn', `${x.label} is outside the room outline`, [x.id], 'placement check', 'move it inside the room');
    if (!x.role || !String(x.role).trim())
      f(`missing-role:${x.id}`, 'missing_device_role', 'Low', 'every device needs an assigned role for the schedule and the tests', `${x.id} has no assigned role`, [x.id], 'schedule check', 'assign a role');
  }

  // 3. PoE budget (declared catalogue values, not measured)
  const sw = live.find((x) => x.cat === 'switch');
  if (sw) {
    const budget = Number(sw.props['poe_budget_w']) || 0;
    const draw = conns
      .filter((c) => c.kind === 'network' && (c.to === sw.id || c.from === sw.id))
      .map((c) => byId.get(c.from === sw.id ? c.to : c.from))
      .filter((y): y is PlannedDevice => !!y)
      .reduce((s, y) => s + (C.categories[y.cat]!.poe || 0), 0);
    if (draw > budget)
      f(`incompatible:${sw.id}:poe`, 'incompatible_components', 'High', `declared PoE draw ${draw} W exceeds the switch's declared budget ${budget} W (catalog values, not measured)`, `PoE budget exceeded on ${sw.label}`, [sw.id], 'compatibility check (declared catalog values)', 'choose a switch with a larger PoE budget or power some devices locally');
  }

  // 4. sightline hypothesis (MODELED rule of thumb: farthest seat ≤ ~8 × image height)
  const disp = live.filter((x) => x.cat === 'display');
  if (disp.length && arch && ['BRD', 'TRN', 'EXE', 'COL'].includes(arch)) {
    const far = Math.max(...live.filter((x) => x.cat === 'chairs').map((c) => Math.min(...disp.map((y) => Math.hypot(c.x - y.x, c.y - y.y)))), 0);
    const imgH = (Number(disp[0]!.props['diagonal_in']) || 75) * 0.0254 * 0.49;
    if (far > imgH * 8)
      f(`sightline:${disp[0]!.id}`, 'placement_constraint', 'Medium', `the farthest seating block is ${far.toFixed(1)} m from the nearest display; a common planning ratio is about 6–8 × the image height (${(imgH * 8).toFixed(1)} m here) — a MODELED rule of thumb, not a verified sightline study`, 'Farthest seats are beyond the modeled viewing distance', disp.map((x) => x.id), 'sightline hypothesis (modeled)', 'larger displays, a second display or seats closer to the screen');
  }

  // 5. competing far-end video sources
  if (has(['camera']) && has(['bar']))
    f('incompatible:camera-and-bar', 'incompatible_components', 'Low', 'a video bar and a separate camera both claim the far-end picture; one must be the designated camera', 'Two video sources compete for the far-end picture', live.filter((x) => ['camera', 'bar'].includes(x.cat)).map((x) => x.id), 'compatibility check', 'designate one camera or remove the video bar');

  return out;
}

/**
 * Commissioning results: the single result vocabulary and the acceptance counts.
 *
 * Rule (audit 253 F-03 and rc3 R3-2): a recorded PASS is PASS_UNVERIFIED until a different person verifies it. No surface, export,
 * event or API returns a bare `PASS`. Ported from `v25RoomResultLabel`, `v25RoomResultCounts`, `v25RoomResultWords`.
 */
import type { ApplicabilityRow, RecordedResult, ResultCounts, ResultLabel } from '@empathia/domain-types';

export function resultLabel(r: RecordedResult | null | undefined): ResultLabel {
  if (!r) return 'NOT_TESTED';
  if (r.state === 'PASS') return r.verified && r.verified.by && r.verified.by !== r.by ? 'PASS_VERIFIED' : 'PASS_UNVERIFIED';
  return r.state;
}

export function resultCounts(rows: ApplicabilityRow[], results: Record<string, RecordedResult> | undefined): ResultCounts {
  const app = rows.filter((r) => r.applicable);
  const R = results || {};
  const L = app.map((r) => resultLabel(R[r.id]));
  const n = (x: ResultLabel) => L.filter((y) => y === x).length;
  return {
    applicable: app.length,
    recorded: L.filter((x) => x !== 'NOT_TESTED').length,
    verified: n('PASS_VERIFIED'),
    awaiting: n('PASS_UNVERIFIED'),
    failed: n('FAIL'),
    notSupported: n('NOT_SUPPORTED'),
    inconclusive: n('INCONCLUSIVE'),
    notTested: n('NOT_TESTED'),
  };
}

export function resultWords(c: ResultCounts): string {
  return [`${c.verified} passed and independently verified`, `${c.awaiting} passed awaiting verification`, `${c.failed} failed`]
    .concat(c.notSupported ? [`${c.notSupported} not supported`] : [])
    .concat(c.inconclusive ? [`${c.inconclusive} inconclusive`] : [])
    .join(', ');
}

/** Acceptance is possible only when every applicable test is PASS_VERIFIED. Returns the blocking reasons (empty = acceptable). */
export function acceptanceBlockers(c: ResultCounts): string[] {
  const why: string[] = [];
  if (c.applicable === 0) why.push('no applicable tests have been judged');
  if (c.verified < c.applicable) why.push(`${c.applicable - c.verified} of ${c.applicable} applicable tests are not passed and independently verified (${resultWords(c)}, ${c.notTested} not tested)`);
  return why;
}

/**
 * Rules for recording and verifying a field result. Ported from `v25RoomRecord` and `v25RoomVerify` (src/v25-60-room.js).
 * Pure validation: the server applies the result only when these return no reasons, and only after its own authority check.
 */
import { RECORDABLE_STATES, type ApplicabilityRow, type RecordableState, type RecordedResult } from '@empathia/domain-types';

export interface RecordInput {
  state: string;
  evidence?: { kind?: string; ref?: string; instrument?: string | null };
}

/** Personas that may record any applicable test besides the test's own responsible personas. */
export const RECORD_OVERRIDE_PERSONAS = ['cxeng', 'architect'];

export function recordBlockers(lifecycle: string, row: ApplicabilityRow | undefined, persona: string, input: RecordInput): string[] {
  if (lifecycle !== 'COMMISSIONING') return [`results are recorded on an installed room in COMMISSIONING (this one is ${lifecycle}): nothing passes from a design`];
  if (!row || !row.applicable) return [`${row ? row.id : 'this test'} does not apply to this room`];
  if (!(row.personas || []).includes(persona) && !RECORD_OVERRIDE_PERSONAS.includes(persona)) return [`${persona} is not the responsible role for ${row.id} (${(row.personas || []).join(', ')})`];
  if (!(RECORDABLE_STATES as readonly string[]).includes(input.state)) return ['state is PASS, FAIL, NOT_SUPPORTED or INCONCLUSIVE'];
  const ev = input.evidence || {};
  if (!(row.evidence || []).includes(ev.kind || '')) return [`evidence kind ${ev.kind || '(none)'} is not accepted for ${row.id}; accepted: ${(row.evidence || []).join(', ')}`];
  if (!ev.ref || String(ev.ref).trim().length < 4) return ['a result needs an evidence reference'];
  if (row.instrument && !ev.instrument) return [`${row.id} is instrument-measured: name the instrument and its calibration`];
  return [];
}

export function buildResult(prev: RecordedResult | undefined, persona: string, input: RecordInput, at: string): RecordedResult {
  const ev = input.evidence || {};
  return {
    state: input.state as RecordableState,
    evidence: { kind: String(ev.kind), ref: String(ev.ref).slice(0, 200), instrument: ev.instrument || null },
    by: persona,
    at,
    verified: null,
    history: prev ? (prev.history || []).concat([{ state: prev.state, by: prev.by, at: prev.at, verified: prev.verified }]) : [],
  };
}

/** Independent verification: only a recorded PASS, never by the person who recorded it, never twice. */
export function verifyBlockers(r: RecordedResult | undefined, persona: string): string[] {
  if (!r || r.state !== 'PASS') return ['only a recorded PASS can be verified'];
  if (r.by === persona) return ['verification must be independent of the person who recorded the result'];
  if (r.verified) return ['already verified'];
  return [];
}

/**
 * Lifecycle gates for a planned room: which authority a transition needs and which conditions block it.
 * Ported from `v25RoomLifecycle` (src/v25-60-room.js). Pure: the caller (enterprise API) checks the authority server-side,
 * applies the transition in a transaction and writes the audit event.
 */
import { ROOM_LIFECYCLE, type ApplicabilityRow, type RecordedResult, type RoomLifecycle } from '@empathia/domain-types';
import { resultCounts, resultWords } from './results.js';

/** The authority each target state requires (the demonstrator's policy names). */
export const LIFECYCLE_AUTHORITY: Record<RoomLifecycle, string> = {
  PLANNED: 'room.design.approve',
  DESIGN_APPROVED: 'room.design.approve',
  INSTALLATION_PENDING: 'window.approve',
  INSTALLED_UNVERIFIED: 'work.evidence',
  COMMISSIONING: 'plan.compile',
  ACCEPTED: 'customer.accept',
  OPERATIONAL: 'handoff.accept',
};

export interface LifecycleFacts {
  from: RoomLifecycle | string;
  to: RoomLifecycle;
  classificationApproved: boolean;
  openIssues: Array<{ severity: string }>;
  savedRevisions: number;
  rows: ApplicabilityRow[];
  results: Record<string, RecordedResult> | undefined;
  hasBaseline: boolean;
  /** Live monitoring evidence on the installed room. The synthetic demonstrator and the starter never have it. */
  hasLiveMonitoringEvidence: boolean;
}

/** Returns the reasons a transition is refused; an empty list means the transition is allowed (authority still to be checked). */
export function lifecycleBlockers(f: LifecycleFacts): string[] {
  const i = ROOM_LIFECYCLE.indexOf(f.from as RoomLifecycle);
  const j = ROOM_LIFECYCLE.indexOf(f.to);
  if (j !== i + 1 && !(f.to === 'PLANNED' && f.from === 'DESIGN_APPROVED')) return [`no transition ${f.from} → ${f.to}: the room moves one governed step at a time`];
  const why: string[] = [];
  if (f.to === 'DESIGN_APPROVED') {
    if (!f.classificationApproved) why.push('the room classification is not approved by an engineer');
    const hi = f.openIssues.filter((x) => x.severity === 'High' || x.severity === 'Critical').length;
    if (hi) why.push(`${hi} open High/Critical design deficiencies`);
    if (!f.savedRevisions) why.push('no saved revision');
  }
  if (f.to === 'ACCEPTED') {
    const app = f.rows.filter((r) => r.applicable);
    if (!app.length || app.some((r) => r.result !== 'PASS_VERIFIED')) {
      const C = resultCounts(f.rows, f.results);
      why.push(`acceptance needs every applicable test executed, passed and independently verified with evidence: ${C.verified} of ${app.length} passed and independently verified (${C.recorded} recorded: ${resultWords(C).replace(/^\d+ passed and independently verified, /, '')}; ${C.notTested} not tested)`);
    }
    if (f.openIssues.length) why.push(`${f.openIssues.length} open issue(s): every deficiency is closed with its retest before acceptance`);
  }
  if (f.to === 'OPERATIONAL') {
    if (!f.hasBaseline) why.push('no accepted, signed baseline');
    if (!f.hasLiveMonitoringEvidence) why.push('operational status needs live monitoring evidence on the installed room; without it the room stays ACCEPTED');
  }
  return why;
}

/**
 * Parity: the TypeScript engines must reproduce the demonstrator's own outputs on 92 golden cases.
 * The golden file is generated by scripts/extract/extract-golden.mjs from a demonstrator build (its sha256 is in the file).
 * A failing case is a FAIL — never edit the golden file to make this pass; regenerate it only from a new demonstrator build.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import { analyzeRoom, resultLabel, verifyBlockers, recordBlockers } from '../src/index.js';

const require = createRequire(import.meta.url);
const goldenPath = require.resolve('@empathia/domain-data/golden/room-engine-golden.json');
const golden = JSON.parse(fs.readFileSync(goldenPath, 'utf8')) as {
  generatedFrom: string;
  sha256: string;
  cases: number;
  errors: unknown[];
  data: Array<{ name: string; input: any; output: any }>;
};

test('golden file is complete', () => {
  assert.equal(golden.errors.length, 0);
  assert.equal(golden.data.length, golden.cases);
  assert.ok(golden.cases >= 90, `expected ≥ 90 cases, found ${golden.cases}`);
});

for (const c of golden.data) {
  test(`parity: ${c.name}`, () => {
    const a = analyzeRoom(c.input);
    const o = c.output;
    const cls = a.classification;
    assert.deepEqual(
      { archetype: cls.archetype, subtype: cls.subtype, capacityEstimate: cls.capacityEstimate, people: cls.people, sizeCategory: cls.sizeCategory, complexity: cls.complexity, families: cls.families, cxRoomType: cls.cxRoomType, confidence: cls.confidence },
      o.classification,
      'classification',
    );
    assert.deepEqual(a.checks.map((f) => ({ key: f.key, check: f.check, severity: f.severity, assets: f.assets })), o.checks, 'design checks');
    const { rows, ...summary } = a.applicability;
    const { rows: grows, ...gsummary } = o.applicability;
    assert.deepEqual(summary, gsummary, 'applicability summary');
    assert.deepEqual(
      // the same serialization the extractor applied (scripts/extract/extract-golden.mjs: result || null, devices || [], missing || [])
      rows.map((r) => ({ id: r.id, applicable: r.applicable, status: r.status, result: r.result || null, devices: r.devices || [], missing: r.missing || [] })),
      grows.map((r: any) => ({ id: r.id, applicable: r.applicable, status: r.status, result: r.result, devices: r.devices, missing: r.missing })),
      'applicability rows',
    );
    assert.deepEqual(a.counts, o.counts, 'result counts');
  });
}

test('R3-2: no row ever carries a bare PASS', () => {
  for (const c of golden.data) for (const r of analyzeRoom(c.input).applicability.rows) assert.notEqual(r.result, 'PASS');
});

test('a PASS recorded and "verified" by the same person stays PASS_UNVERIFIED', () => {
  assert.equal(resultLabel({ state: 'PASS', evidence: { kind: 'FIELD_OBSERVED', ref: 'EV-1' }, by: 'cxeng', verified: { by: 'cxeng' } }), 'PASS_UNVERIFIED');
  assert.equal(resultLabel({ state: 'PASS', evidence: { kind: 'FIELD_OBSERVED', ref: 'EV-1' }, by: 'cxeng', verified: { by: 'qa_reviewer' } }), 'PASS_VERIFIED');
  assert.deepEqual(verifyBlockers({ state: 'PASS', evidence: { kind: 'X', ref: 'EV-1' }, by: 'cxeng', verified: null }, 'cxeng'), ['verification must be independent of the person who recorded the result']);
});

test('a design never records a result', () => {
  const why = recordBlockers('PLANNED', { id: 't', applicable: true } as any, 'cxeng', { state: 'PASS', evidence: { kind: 'FIELD_OBSERVED', ref: 'EV-123' } });
  assert.match(why[0]!, /nothing passes from a design/);
});

