.film.portrait .thumb { aspect-ratio: 16 / 9; }
.film:hover .thumb { border-color: var(--accent); }
.film b { font-size: var(--fs-sm); }
.film span { font-size: var(--fs-xs); color: var(--tx3); }
.player { display: grid; gap: var(--sp-3); }
.player video { width: 100%; max-height: 72vh; background: #000; border-radius: var(--r-md); }
.player-wrap { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: var(--sp-5); align-items: start; }

/* ---------------------------------------------------------------- code and documents */
.code { margin: 0; padding: var(--sp-4); overflow: auto; max-height: 70vh; background: var(--bg2); border: 1px solid var(--line); border-radius: var(--r-sm); font-size: 12.5px; line-height: 1.55; tab-size: 2; }
.code .ln { display: inline-block; width: 3.4em; color: var(--tx3); user-select: none; text-align: right; margin-right: 1em; }
.doc { line-height: 1.6; max-width: 82ch; }
.doc h1 { font-size: var(--fs-xl); margin: 0 0 var(--sp-4); }
.doc h2 { font-size: var(--fs-lg); margin: var(--sp-6) 0 var(--sp-3); }
.doc h3 { margin: var(--sp-5) 0 var(--sp-2); }
.doc p, .doc ul, .doc ol { margin: 0 0 var(--sp-3); }
.doc table { border-collapse: collapse; margin: 0 0 var(--sp-4); font-size: var(--fs-sm); display: block; overflow-x: auto; }
.doc th, .doc td { border: 1px solid var(--line2); padding: 6px 10px; text-align: left; vertical-align: top; }
.doc th { background: var(--panel2); }
.doc code { background: var(--panel2); padding: 1px 5px; border-radius: 5px; }
.doc pre { background: var(--bg2); padding: var(--sp-3); border-radius: var(--r-sm); overflow-x: auto; }
.doc pre code { background: none; padding: 0; }
.doc-layout { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: var(--sp-5); align-items: start; }
.doc-index { position: sticky; top: 72px; max-height: calc(100vh - 96px); overflow: auto; display: grid; gap: var(--sp-3); }
.doc-index a { display: block; padding: 4px var(--sp-2); border-radius: 6px; color: var(--tx2); text-decoration: none; font-size: var(--fs-sm); }
.doc-index a[aria-current="page"], .doc-index a:hover { background: var(--panel2); color: var(--tx); }
.diagram { overflow-x: auto; padding: var(--sp-4); background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-md); }
.diagram svg { max-width: 100%; height: auto; }
.tabs { display: flex; flex-wrap: wrap; gap: 4px; border-bottom: 1px solid var(--line); }
.tabs button, .tabs a { padding: 8px 12px; border: 0; background: none; color: var(--tx2); cursor: pointer; border-bottom: 2px solid transparent; text-decoration: none; font-size: var(--fs-sm); }
.tabs [aria-selected="true"], .tabs [aria-current="page"] { color: var(--tx); border-bottom-color: var(--accent); }

/* ---------------------------------------------------------------- search palette */
.palette-bg { position: fixed; inset: 0; z-index: 60; background: color-mix(in srgb, var(--bg) 60%, transparent); backdrop-filter: blur(4px); display: grid; place-items: start center; padding-top: 12vh; }
.palette { width: min(680px, calc(100vw - 32px)); background: var(--panel); border: 1px solid var(--line2); border-radius: var(--r-md); box-shadow: var(--shadow); overflow: hidden; }
.palette input { width: 100%; padding: var(--sp-4); border: 0; border-bottom: 1px solid var(--line); background: transparent; font-size: var(--fs-md); outline: none; }
.palette ul { list-style: none; margin: 0; padding: var(--sp-2); max-height: 50vh; overflow: auto; }
.palette li a { display: grid; grid-template-columns: 110px minmax(0, 1fr); gap: var(--sp-3); padding: 8px var(--sp-3); border-radius: 8px; color: var(--tx); text-decoration: none; }
.palette li a[aria-selected="true"] { background: var(--accent-bg); }
.palette li .kind { color: var(--tx3); font-size: var(--fs-xs); padding-top: 2px; }
.palette li small { display: block; color: var(--tx3); }

/* ---------------------------------------------------------------- engine lab */
.lab { display: grid; grid-template-columns: 320px minmax(0, 1fr); gap: var(--sp-5); align-items: start; }
.lab label { display: grid; gap: 4px; font-size: var(--fs-sm); color: var(--tx2); }
.lab input[type="range"] { width: 100%; accent-color: var(--accent); }
.lab select, .field { background: var(--bg2); border: 1px solid var(--line2); border-radius: 8px; padding: 6px 10px; }
.check { display: flex; gap: var(--sp-2); align-items: center; font-size: var(--fs-sm); }
.bars { display: grid; gap: 6px; }
.bar { display: grid; grid-template-columns: 210px minmax(0, 1fr) 44px; gap: var(--sp-3); align-items: center; font-size: var(--fs-sm); }
.bar .track { height: 10px; border-radius: 4px; background: var(--line); overflow: hidden; }
.bar .fill { height: 100%; border-radius: 4px; background: var(--accent); }

/* ---------------------------------------------------------------- responsive */
@media (max-width: 1180px) {
  .split, .player-wrap { grid-template-columns: minmax(0, 1fr); }
  .lab { grid-template-columns: minmax(0, 1fr); }
  .status-band { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 900px) {
  .shell { grid-template-columns: minmax(0, 1fr); }
  .rail { position: fixed; z-index: 40; left: 0; top: 0; width: 290px; transform: translateX(-100%); transition: transform var(--t-med) var(--ease); box-shadow: var(--shadow); }
  .shell.rail-open .rail { transform: none; }
  .menu-btn { display: inline-grid; }
  .doc-layout { grid-template-columns: minmax(0, 1fr); }
  .doc-index { position: static; max-height: none; }
  .cols-2, .cols-3 { grid-template-columns: minmax(0, 1fr); }
  .page { padding: var(--sp-4) var(--sp-4) var(--sp-7); }
  .topbar { padding: var(--sp-2) var(--sp-4); }
  .search-btn { min-width: 0; }
  .search-btn .label { display: none; }
  .demo { height: 78vh; }
  .ledger .pitch { display: none; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; } }
:root[data-motion="reduced"] *, :root[data-motion="reduced"] *::before { transition: none !important; animation: none !important; }

/* diagrams are rendered twice (dark and light Mermaid themes); the page theme picks one */
.dia-light { display: none; }
@media (prefers-color-scheme: light) { :root:not([data-theme="dark"]) .dia-dark { display: none; } :root:not([data-theme="dark"]) .dia-light { display: block; } }
:root[data-theme="light"] .dia-dark { display: none; }
:root[data-theme="light"] .dia-light { display: block; }

