/* ==== Version 1.3.3 · AURORA: one design language, three device compositions ==========================================
   The tokens below are the whole visual identity: midnight navy canvases, electric cyan for interaction and selection,
   indigo and violet for depth and for Learn, emerald / amber / red for state (always with a word or a shape beside the
   colour). Every surface in the app reads these tokens, so the look is set here once. The role canvases of version 1.1
   (bright limestone for a visitor, ledger grey for a steward…) are retired in 1.3.3: a product has a mood now, not a role.
   The mood is set on <html data-mood> by the route family (Pro · Lite · Learn · Search · Service · Campus). */

html[data-skin="aurora"] {
  --bg: #070d1a; --bg2: #0a1222; --panel: #0f1a30; --panel2: #16233e; --bg-rgb: 7, 13, 26; --ink: 214, 228, 255;
  --line: rgba(214, 228, 255, 0.09); --line2: rgba(214, 228, 255, 0.17); --tx: #edf3ff; --tx2: #aebbd8; --tx3: #7f8fae;
  --teal: #3fd8ff; --acc: 63, 216, 255; --teal-bg: rgba(63, 216, 255, 0.11);
  --cyan: #3fd8ff; --indigo: #6473ff; --violet: #a68cff; --emerald: #3ddc97;
  --ok: #3ddc97; --warn: #f5b942; --bad: #ff6b6b; --info: #7aa7ff; --learn: #a68cff;
  --display: var(--sans); --r: 14px; --rx: 0px;
  --mood-a: 63, 216, 255; --mood-b: 100, 115, 255;   /* the aurora glow: a cool pair the mood retunes */
  --glass: rgba(15, 26, 48, 0.78); --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 14px 40px rgba(2, 6, 18, 0.5);
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1); --t-fast: 160ms; --t-med: 240ms;
  color-scheme: dark;
}
html[data-skin="aurora"][data-mood="lite"] { --mood-a: 63, 216, 255; --mood-b: 36, 99, 235; }
html[data-skin="aurora"][data-mood="learn"] { --mood-a: 166, 140, 255; --mood-b: 100, 115, 255; --teal: #b39dff; --acc: 179, 157, 255; --teal-bg: rgba(179, 157, 255, 0.12); }
html[data-skin="aurora"][data-mood="search"] { --mood-a: 100, 115, 255; --mood-b: 63, 216, 255; }
html[data-skin="aurora"][data-mood="service"] { --mood-a: 245, 185, 66; --mood-b: 100, 115, 255; --teal: #ffcb63; --acc: 255, 203, 99; --teal-bg: rgba(255, 203, 99, 0.11); }
html[data-skin="aurora"][data-mood="pro"] { --mood-a: 63, 216, 255; --mood-b: 61, 220, 151; }
html[data-skin="aurora"][data-mood="campus"] { --mood-a: 63, 216, 255; --mood-b: 36, 99, 235; }

/* ---- the canvas: a quiet aurora at the top of every page, never a glow on every card */
html[data-skin="aurora"] .view { background-color: var(--bg);
  background-image: radial-gradient(900px 420px at 18% -6%, rgba(var(--mood-a), 0.16), transparent 60%), radial-gradient(760px 380px at 86% -10%, rgba(var(--mood-b), 0.16), transparent 60%);
  background-attachment: local; background-repeat: no-repeat; }
html[data-skin="aurora"] .top { background: rgba(var(--bg-rgb), 0.86); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }
html[data-skin="aurora"] .tabs { background: rgba(var(--bg-rgb), 0.92); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }
html[data-skin="aurora"] .page-h, html[data-skin="aurora"] .lede { font-family: var(--sans); font-weight: 700; letter-spacing: -0.022em; }
