html[data-skin="aurora"] .btn.go { background: var(--teal-bg); border-color: rgba(var(--acc), 0.4); color: var(--teal); }
html[data-skin="aurora"] .pill.on, html[data-skin="aurora"] .seg.on, html[data-skin="aurora"] .lens-sel a.on { background: var(--teal-bg); border-color: rgba(var(--acc), 0.55); color: var(--teal); }
html[data-skin="aurora"] .search { background: rgba(214, 228, 255, 0.05); border-color: var(--line2); box-shadow: 0 0 0 0 rgba(var(--acc), 0); transition: box-shadow var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); }
