html[data-skin="aurora"] .strip { background: var(--bg); }
html[data-skin="aurora"] .sheet, html[data-skin="aurora"] .sheet.small { background: var(--glass); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); box-shadow: var(--shadow); }
html[data-skin="aurora"] .tab.on { color: var(--teal); }
html[data-skin="aurora"] .tab.on svg { filter: drop-shadow(0 0 6px rgba(var(--acc), 0.55)); }
html[data-skin="aurora"] :focus-visible { outline-color: var(--teal); }
html[data-skin="aurora"] .ctx { border-radius: 999px; padding: 3px 8px; }
html[data-skin="aurora"] .ctx.teal, html[data-skin="aurora"] .ctx.on { color: var(--teal); border-color: rgba(var(--acc), 0.45); }
html[data-skin="aurora"] .zone h2 { font-size: 15.5px; letter-spacing: -0.005em; }
html[data-skin="aurora"] .row:hover { background: rgba(214, 228, 255, 0.03); }
html[data-skin="aurora"] .stat .v, html[data-skin="aurora"] .kt-v { letter-spacing: -0.02em; }

/* ---- the Aurora hero: one per page at most, drawn by the shell, never stacked on a legacy one */
.au-hero { position: relative; overflow: hidden; border-radius: 20px; border: 1px solid var(--line2); padding: 22px 22px 20px; margin-bottom: 18px;
  background: radial-gradient(640px 300px at 100% 0%, rgba(var(--mood-b), 0.3), transparent 60%), radial-gradient(520px 260px at 0% 100%, rgba(var(--mood-a), 0.22), transparent 60%), linear-gradient(180deg, #0e1a33, #0a1326); }
.au-hero::after { content: ""; position: absolute; inset: 0; background-image: linear-gradient(rgba(214, 228, 255, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(214, 228, 255, 0.05) 1px, transparent 1px); background-size: 48px 48px; mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.5), transparent 80%); -webkit-mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.5), transparent 80%); pointer-events: none; }
.au-hero > * { position: relative; z-index: 1; }
.au-eyebrow { display: flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--teal); }
.au-eyebrow i { width: 7px; height: 7px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 10px var(--teal); }
.au-hero h1 { font-size: 30px; line-height: 1.08; letter-spacing: -0.025em; font-weight: 760; margin-top: 10px; max-width: 18ch; text-wrap: balance; }
.au-hero .sub { max-width: 58ch; margin-top: 8px; font-size: 14.5px; }
.au-acts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.au-acts .btn { min-height: 42px; }
.au-stats { display: flex; gap: 14px 22px; flex-wrap: wrap; margin-top: 16px; }
.au-stats b { display: block; font-size: 22px; font-weight: 720; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.au-stats span { font-size: 12px; color: var(--tx2); }
.au-stats a { color: inherit; } .au-stats a:hover b { color: var(--teal); }
.au-next { display: grid; gap: 10px; grid-template-columns: 1fr; margin-top: 16px; }
.au-next a { display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; align-items: center; gap: 12px; min-height: 60px; padding: 10px 14px; border-radius: 14px; border: 1px solid var(--line2); background: rgba(7, 13, 26, 0.55); color: inherit; transition: border-color var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }
.au-next a:hover, .au-next a:focus-visible { border-color: rgba(var(--acc), 0.6); transform: translateY(-1px); }
.au-next .kt-i { width: 38px; height: 38px; }
.au-next b { display: block; font-size: 14.5px; font-weight: 640; line-height: 1.25; }
.au-next i { display: block; font-style: normal; font-size: 12px; color: var(--tx3); margin-top: 1px; }
.au-next .go { color: var(--teal); font-size: 12px; font-weight: 700; white-space: nowrap; }
.au-recent { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.au-recent a { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--line2); font-size: 13px; color: var(--tx2); background: rgba(7, 13, 26, 0.45); }
.au-recent a svg { width: 15px; height: 15px; color: var(--teal); }
.au-fold { margin-top: 22px; border-top: 1px solid var(--line); }
.au-fold > summary { list-style: none; cursor: pointer; display: flex; align-items: center; gap: 10px; min-height: 48px; font-weight: 650; font-size: 14.5px; }
.au-fold > summary::-webkit-details-marker { display: none; }
.au-fold > summary::before { content: ""; width: 8px; height: 8px; border-right: 2px solid var(--tx3); border-bottom: 2px solid var(--tx3); transform: rotate(-45deg); transition: transform var(--t-fast) var(--ease); margin-left: 4px; }
.au-fold[open] > summary::before { transform: rotate(45deg); }
.au-fold > summary .hint { font-weight: 500; color: var(--tx3); font-size: 12.5px; margin-left: auto; }

/* ---- the role gate: the first screen of a fresh open */
