  background-image: radial-gradient(900px 520px at 16% -10%, rgba(63, 216, 255, 0.2), transparent 60%), radial-gradient(900px 520px at 90% 0%, rgba(100, 115, 255, 0.24), transparent 62%), radial-gradient(700px 500px at 50% 110%, rgba(166, 140, 255, 0.14), transparent 60%); }
