.rg-copy h1 { font-size: 34px; line-height: 1.04; letter-spacing: -0.03em; font-weight: 780; max-width: 14ch; text-wrap: balance; }
.rg-copy h1 em { font-style: normal; color: var(--cyan); }
.rg-copy p { margin-top: 8px; color: var(--tx2); max-width: 52ch; font-size: 14.5px; }
.rg-search { margin-top: 16px; }
.rg-search .search { height: 54px; border-radius: 27px; background: rgba(15, 26, 48, 0.92); border-color: rgba(63, 216, 255, 0.45); box-shadow: 0 10px 40px rgba(2, 6, 18, 0.5); }
