.rg-h2 { margin-top: 24px; display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.rg-h2 h2 { font-size: 15px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--tx2); }
.rg-h2 .hint { font-size: 12.5px; color: var(--tx3); }
.rg-roles { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 12px; }
